            <div style={{ display: 'flex', gap: '14px', alignItems: 'flex-start' }}><span style={{ flex: '0 0 30px', height: '30px', borderRadius: '50%', background: '#d97706', color: '#ffffff', fontSize: '12px', fontWeight: 800, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>1</span><div><div style={{ fontSize: '16px', fontWeight: 800, color: '#111111' }}>Balance first</div><p style={{ margin: '4px 0 0', fontSize: '14px', lineHeight: 1.7, color: '#4b5563' }}>"All your money!" sits on a patterned card with Add Money on it and a toggle to hide the amount.</p></div></div>
